#include <cstdio>
#include <vector>

struct Node {
    int val;
    Node* next;
    Node(int v) : val(v), next(nullptr) {}
};

int main() {
    int n;
    scanf("%d", &n);
    std::vector<Node*> nodes(n + 1, nullptr);
    for (int i = 1; i <= n; ++i) {
        int v;
        scanf("%d", &v);
        nodes[i] = new Node(v);
    }
    for (int i = 1; i <= n; ++i) {
        int to;
        scanf("%d", &to);
        nodes[i]->next = (to == 0) ? nullptr : nodes[to];
    }

    Node* slow = nodes[1];
    Node* fast = nodes[1];
    bool hasCycle = false;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) { hasCycle = true; break; }
    }
    printf("%s\n", hasCycle ? "YES" : "NO");
    return 0;
}
